"OLAYLAR_ARKEOLOJI_D3_HINT_CIN:-0201-01-01:0":{"b": ["Avakirina xanedana Han - îlankirina Liu Bang wek împerator (B.Z. 202): xanedana Han a Rojava tê avakirin", "b6d66651"], "d": ["Piştî şerê Chu-Han, Liu Bang di sala 5an a Han de nasnavê împeratorî wergirt; serdema Han a Rojava ji 202an dest pê dikin.", "c15c87db"]},
"OLAYLAR_ARKEOLOJI_D3_HINT_CIN:-0236-01-01:0":{"b": ["Serdestiya Aşoka û hevdemkirina bi Fermana Zinarî ya XIII.: Aşoka dimire", "39f8eb23"], "d": ["Serdestiya Aşoka: li gorî CHI 1922 derketina ser text ≤274, tac li serxwedan ≤270, fetha Kalinga ≤262, mirin 237/236 B.Z. Fermana Zinarî ya XIII. pênc qralên Helenîstîk (Antiochos, Ptolemaios, Antigonos, Magas, Îskender) wek sax dihesibîne; CHI ji ber mirina Magas di 258an de fermanê bi awayekî demkî di 'nêzîkî 258-257 B.Z.' de datîne.", "62399b89"]},
"OLAYLAR_ARKEOLOJI_D3_HINT_CIN:-0273-01-01:0":{"b": ["Serdestiya Aşoka û hevdemkirina bi Fermana Zinarî ya XIII.: Aşoka derdikeve ser text", "7a0e6e1c"], "d": ["Serdestiya Aşoka: li gorî CHI 1922 derketina ser text ≤274, tac li serxwedan ≤270, fetha Kalinga ≤262, mirin 237/236 B.Z. Fermana Zinarî ya XIII. pênc qralên Helenîstîk (Antiochos, Ptolemaios, Antigonos, Magas, Îskender) wek sax dihesibîne; CHI ji ber mirina Magas di 258an de fermanê bi awayekî demkî di 'nêzîkî 258-257 B.Z.' de datîne.", "62399b89"]},
